/**
 * Hospitalist Workflow Tracker — Autogenerated Sign-Out & Transfer Handoff Engine
 * Generates I-PASS Shift Sign-Outs and Comprehensive Service Transfer Handoffs.
 */

const SignOutEngine = (() => {
  function sortForHandoff(patients, sortBy = 'priority') {
    const copy = [...patients];
    if (sortBy === 'room') {
      return copy.sort((a, b) => a.room.localeCompare(b.room, undefined, { numeric: true }));
    }
    return copy.sort((a, b) => {
      const rankA = PRIORITY_META[a.priority]?.rank ?? 99;
      const rankB = PRIORITY_META[b.priority]?.rank ?? 99;
      if (rankA !== rankB) return rankA - rankB;
      return a.room.localeCompare(b.room, undefined, { numeric: true });
    });
  }

  function formatTimestamp() {
    const now = new Date();
    return now.toLocaleString(undefined, {
      year: 'numeric',
      month: 'short',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  function getMissingChecklistLabels(patient) {
    const allDefs = [...CHECKLIST_DEFINITIONS.preround, ...CHECKLIST_DEFINITIONS.encounter];
    return allDefs.filter(d => !patient.checklist?.[d.id]).map(d => d.short);
  }

  function buildPatientTextBlock(patient, options) {
    const { mode, includeCompletedTasks, includeDataSnapshot, includeChecklistGaps } = options;
    const pMeta = PRIORITY_META[patient.priority] || PRIORITY_META.stable;
    const openTasks = (patient.tasks || []).filter(t => !t.done);
    const doneTasks = (patient.tasks || []).filter(t => t.done);
    const activeConsults = (patient.consults || []).filter(c => c.status !== 'Signed Off');
    const allConsults = patient.consults || [];
    const lines = [];

    lines.push(`━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`);
    lines.push(
      `[${pMeta.shortLabel}]  Room ${patient.room} — ${patient.name} (${patient.age}${patient.sex})  ·  HD #${patient.hospitalDay}  ·  ${patient.codeStatus}`
    );
    lines.push(`Primary Dx: ${patient.primaryDx || '—'}   |   Allergies: ${patient.allergies?.trim() || 'NOT RECORDED'}`);
    lines.push('');

    // I - Illness Severity & P - Patient Summary
    lines.push(`ILLNESS SEVERITY: ${pMeta.label}`);
    lines.push('');
    lines.push(`PATIENT SUMMARY:`);
    lines.push(`  ${patient.oneLiner || 'No one-liner documented.'}`);

    if (includeDataSnapshot) {
      const snapLines = [];
      if (patient.vitalsSummary) snapLines.push(`  • Vitals / Tele: ${patient.vitalsSummary}`);
      if (patient.labsSummary) snapLines.push(`  • Key Labs: ${patient.labsSummary}`);
      if (patient.ioSummary) snapLines.push(`  • Outputs / I&O: ${patient.ioSummary}`);
      if (patient.lastBm) snapLines.push(`  • Last BM: ${patient.lastBm}`);
      if (patient.weightSummary) snapLines.push(`  • Weight: ${patient.weightSummary}`);
      if (patient.imagingSummary) snapLines.push(`  • Imaging: ${patient.imagingSummary}`);
      if (snapLines.length > 0) {
        lines.push('');
        lines.push(...snapLines);
      }
    }

    if (mode === 'transfer' && patient.clinicalNotes) {
      lines.push('');
      lines.push(`HOSPITAL COURSE & ACTIVE PLAN:`);
      patient.clinicalNotes.split('\n').forEach(l => lines.push(`  ${l}`));
    } else if (mode === 'shift' && patient.clinicalNotes) {
      lines.push('');
      lines.push(`CLINICAL CONTEXT:`);
      lines.push(`  ${patient.clinicalNotes.replace(/\n+/g, ' ')}`);
    }

    // Consults (uses condensed recs if available)
    const consultList = mode === 'transfer' ? allConsults : activeConsults;
    if (consultList.length > 0) {
      lines.push('');
      lines.push(`CONSULTS:`);
      consultList.forEach(c => {
        const recText = (c.condensedNotes || c.notes || '').trim();
        lines.push(`  • ${c.service} (${c.status})${recText ? ': ' + recText : ''}`);
      });
    }

    // A - Action List
    lines.push('');
    lines.push(`ACTION LIST (PENDING TO-DOS):`);
    if (openTasks.length === 0) {
      lines.push(`  • None — no pending tasks.`);
    } else {
      const sortedTasks = [...openTasks].sort((a, b) => Number(b.urgent) - Number(a.urgent));
      sortedTasks.forEach(t => {
        const tag = t.urgent ? '[STAT] ' : '';
        lines.push(`  [ ] ${tag}(${t.category}) ${t.text}`);
      });
    }
    if (includeCompletedTasks && doneTasks.length > 0) {
      lines.push('');
      lines.push(`  Completed Today:`);
      doneTasks.forEach(t => lines.push(`  [x] (${t.category}) ${t.text}`));
    }

    // S - Situation Awareness & Contingency Planning
    lines.push('');
    lines.push(`CONTINGENCIES (IF / THEN):`);
    lines.push(`  • ${patient.contingencies || 'Routine floor monitoring; call hospitalist for acute change in vitals or mental status.'}`);

    // Disposition
    if (mode === 'transfer' || patient.priority === 'discharge') {
      lines.push('');
      lines.push(`DISPOSITION & BARRIERS:`);
      lines.push(`  • ${patient.disposition || 'Pending daily reassessment.'}`);
    }

    if (includeChecklistGaps) {
      const gaps = getMissingChecklistLabels(patient);
      if (gaps.length > 0) {
        lines.push('');
        lines.push(`UNCHECKED ITEMS: ${gaps.join(', ')}`);
      }
    }

    lines.push('');
    lines.push('');
    return lines.join('\n');
  }

  function generateText(state, options = {}) {
    const opts = {
      mode: 'shift', // 'shift' | 'transfer' | 'single'
      patientId: null,
      onlySickAndWatcher: false,
      sortBy: 'priority',
      includeCompletedTasks: false,
      includeDataSnapshot: false,
      includeChecklistGaps: false,
      ...options
    };

    let list = [...state.patients];
    if (opts.mode === 'single') {
      list = list.filter(p => p.id === opts.patientId);
    } else if (opts.onlySickAndWatcher) {
      list = list.filter(p => p.priority === 'sick' || p.priority === 'watcher');
    }

    const sorted = sortForHandoff(list, opts.sortBy);
    const effectiveMode = opts.mode === 'single' ? 'transfer' : opts.mode;

    const sickCount = sorted.filter(p => p.priority === 'sick').length;
    const watcherCount = sorted.filter(p => p.priority === 'watcher').length;
    const dcCount = sorted.filter(p => p.priority === 'discharge').length;
    const stableCount = sorted.filter(p => p.priority === 'stable').length;
    const openTaskCount = sorted.reduce((acc, p) => acc + (p.tasks || []).filter(t => !t.done).length, 0);

    const titleMap = {
      shift: 'HOSPITALIST SHIFT SIGN-OUT (I-PASS CROSS-COVER HANDOFF)',
      transfer: 'HOSPITALIST SERVICE TRANSFER / DAY-TO-DAY HANDOFF',
      single: 'PATIENT TRANSFER / HANDOFF SUMMARY'
    };

    const header = [
      `${titleMap[opts.mode] || titleMap.shift}`,
      ``,
      `Service:    ${state.serviceName || 'Hospitalist Medicine'}`,
      `Provider:   ${state.providerName || 'Hospitalist'}`,
      `Generated:  ${formatTimestamp()}`,
      `Census:     ${sorted.length} patient(s)  —  Sick: ${sickCount}  |  Watcher: ${watcherCount}  |  D/C Today: ${dcCount}  |  Stable: ${stableCount}`,
      `Open Tasks: ${openTaskCount}`,
      ``
    ];

    if (sickCount > 0 && opts.mode !== 'single') {
      header.push(`PRIORITY WATCH — SICK PATIENTS FIRST:`);
      sorted
        .filter(p => p.priority === 'sick')
        .forEach(p => header.push(`  • Room ${p.room} — ${p.name} (${p.primaryDx})`));
      header.push('');
    }

    const body = sorted.map(p => buildPatientTextBlock(p, { ...opts, mode: effectiveMode }));

    const footer = [
      `━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━`,
      `RECEIVER SYNTHESIS:`,
      `Review SICK & WATCHER contingencies first, verify pending STAT tasks, and clarify any active questions.`
    ];

    return [...header, ...body, ...footer].join('\n');
  }

  function generateMarkdown(state, options = {}) {
    const opts = {
      mode: 'shift',
      patientId: null,
      onlySickAndWatcher: false,
      sortBy: 'priority',
      includeCompletedTasks: false,
      includeDataSnapshot: false,
      includeChecklistGaps: false,
      ...options
    };

    let list = [...state.patients];
    if (opts.mode === 'single') {
      list = list.filter(p => p.id === opts.patientId);
    } else if (opts.onlySickAndWatcher) {
      list = list.filter(p => p.priority === 'sick' || p.priority === 'watcher');
    }
    const sorted = sortForHandoff(list, opts.sortBy);
    const effectiveMode = opts.mode === 'single' ? 'transfer' : opts.mode;

    const lines = [];
    lines.push(`# ${opts.mode === 'shift' ? 'Shift Sign-Out (I-PASS)' : 'Service Transfer Handoff'}`);
    lines.push(`**Service:** ${state.serviceName} | **Provider:** ${state.providerName} | **Generated:** ${formatTimestamp()}`);
    lines.push('');

    sorted.forEach(p => {
      const pMeta = PRIORITY_META[p.priority] || PRIORITY_META.stable;
      const openTasks = (p.tasks || []).filter(t => !t.done);
      lines.push(`## [${pMeta.shortLabel}] Rm ${p.room} — ${p.name} (${p.age}${p.sex}, HD#${p.hospitalDay}, ${p.codeStatus})`);
      lines.push(`- **Primary Dx:** ${p.primaryDx} | **Allergies:** ${p.allergies?.trim() || 'NOT RECORDED'}`);
      lines.push(`- **Summary:** ${p.oneLiner}`);
      if (opts.includeDataSnapshot) {
        if (p.vitalsSummary) lines.push(`- **Vitals/Tele:** ${p.vitalsSummary}`);
        if (p.labsSummary) lines.push(`- **Key Labs:** ${p.labsSummary}`);
        if (p.ioSummary) lines.push(`- **Outputs/I&O:** ${p.ioSummary}`);
        if (p.weightSummary) lines.push(`- **Weights:** ${p.weightSummary}`);
      }
      if (p.clinicalNotes) lines.push(`- **Clinical Plan:** ${p.clinicalNotes}`);
      if (p.consults?.length) {
        lines.push(`- **Consults:** ${p.consults.map(c => `${c.service} (${c.status}${c.notes ? ': ' + c.notes : ''})`).join('; ')}`);
      }
      lines.push(`- **Action Items:**`);
      if (openTasks.length === 0) {
        lines.push(`  - None`);
      } else {
        openTasks.forEach(t => lines.push(`  - [ ] ${t.urgent ? '**[URGENT]** ' : ''}(${t.category}) ${t.text}`));
      }
      lines.push(`- **Contingencies (If/Then):** ${p.contingencies || 'Routine monitoring.'}`);
      if (effectiveMode === 'transfer' || p.priority === 'discharge') {
        lines.push(`- **Disposition:** ${p.disposition || 'TBD'}`);
      }
      lines.push('');
    });

    return lines.join('\n');
  }

  function escHtml(str) {
    return String(str ?? '')
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function generateFormattedHtml(state, options = {}) {
    const opts = {
      mode: 'shift',
      patientId: null,
      onlySickAndWatcher: false,
      sortBy: 'priority',
      includeCompletedTasks: false,
      includeDataSnapshot: false,
      includeChecklistGaps: false,
      ...options
    };

    let list = [...state.patients];
    if (opts.mode === 'single') {
      list = list.filter(p => p.id === opts.patientId);
    } else if (opts.onlySickAndWatcher) {
      list = list.filter(p => p.priority === 'sick' || p.priority === 'watcher');
    }
    const sorted = sortForHandoff(list, opts.sortBy);
    const effectiveMode = opts.mode === 'single' ? 'transfer' : opts.mode;

    const sickCount = sorted.filter(p => p.priority === 'sick').length;
    const watcherCount = sorted.filter(p => p.priority === 'watcher').length;
    const dcCount = sorted.filter(p => p.priority === 'discharge').length;
    const stableCount = sorted.filter(p => p.priority === 'stable').length;
    const openTaskCount = sorted.reduce((acc, p) => acc + (p.tasks || []).filter(t => !t.done).length, 0);

    const titleMap = {
      shift: 'Hospitalist Shift Sign-Out (I-PASS Handoff)',
      transfer: 'Hospitalist Service Transfer Handoff',
      single: 'Patient Transfer / Handoff Summary'
    };

    const sickBannerHtml = (sickCount > 0 && opts.mode !== 'single')
      ? `<div class="so-sheet-alert">
          <div class="so-sheet-alert-title">PRIORITY WATCH — SICK PATIENTS FIRST</div>
          <ul class="so-sheet-alert-list">
            ${sorted.filter(p => p.priority === 'sick').map(p => `
              <li><strong>Room ${escHtml(p.room)} — ${escHtml(p.name)}</strong> (${escHtml(p.primaryDx || 'Acute')})</li>
            `).join('')}
          </ul>
        </div>`
      : '';

    const cardsHtml = sorted.length === 0
      ? `<div class="so-sheet-empty">No patients match the selected sign-out filters.</div>`
      : sorted.map(p => {
        const pMeta = PRIORITY_META[p.priority] || PRIORITY_META.stable;
        const openTasks = (p.tasks || []).filter(t => !t.done).sort((a, b) => Number(b.urgent) - Number(a.urgent));
        const doneTasks = (p.tasks || []).filter(t => t.done);
        const activeConsults = (p.consults || []).filter(c => c.status !== 'Signed Off');
        const consultList = effectiveMode === 'transfer' ? (p.consults || []) : activeConsults;
        const isDnr = !/^full code$/i.test(p.codeStatus || '');
        const hasAllergy = !p.allergies?.trim() || !/^nkda$/i.test(p.allergies.trim());

        const dataItems = [];
        if (opts.includeDataSnapshot) {
          if (p.vitalsSummary) dataItems.push(['Vitals / Tele', p.vitalsSummary]);
          if (p.labsSummary) dataItems.push(['Key Labs', p.labsSummary]);
          if (p.ioSummary) dataItems.push(['Outputs / I&O', p.ioSummary]);
          if (p.lastBm) dataItems.push(['Last BM', p.lastBm]);
          if (p.weightSummary) dataItems.push(['Weight', p.weightSummary]);
          if (p.imagingSummary) dataItems.push(['Imaging', p.imagingSummary]);
        }

        const gaps = opts.includeChecklistGaps ? getMissingChecklistLabels(p) : [];

        return `
          <article class="so-pt-card so-prio-${escHtml(p.priority)}">
            <div class="so-pt-header">
              <div class="so-pt-id-group">
                <span class="so-pt-room">Rm ${escHtml(p.room)}</span>
                <span class="so-pt-name">${escHtml(p.name)}</span>
                <span class="so-pt-demo">${escHtml(p.age)}${escHtml(p.sex)} · HD #${escHtml(p.hospitalDay)}</span>
              </div>
              <div class="so-pt-badges">
                <span class="so-pt-acuity so-acuity-${escHtml(p.priority)}">${escHtml(pMeta.shortLabel)}</span>
                <span class="so-pt-code ${isDnr ? 'is-dnr' : ''}">${escHtml(p.codeStatus || 'Full Code')}</span>
              </div>
            </div>

            <div class="so-pt-subbar">
              <div><strong>Primary Dx:</strong> ${escHtml(p.primaryDx || '—')}</div>
              <div class="${hasAllergy ? 'so-pt-allergy-warn' : ''}"><strong>Allergies:</strong> ${escHtml(p.allergies?.trim() || 'NOT RECORDED')}</div>
            </div>

            <div class="so-pt-body">
              <div class="so-sec">
                <div class="so-sec-label">Patient Summary</div>
                <div class="so-sec-text">${escHtml(p.oneLiner || 'No one-liner documented.')}</div>
              </div>

              ${dataItems.length > 0 ? `
                <div class="so-sec">
                  <div class="so-sec-label">Clinical Data Snapshot</div>
                  <div class="so-data-grid">
                    ${dataItems.map(([k, v]) => `
                      <div class="so-data-row"><strong>${escHtml(k)}:</strong> <span>${escHtml(v)}</span></div>
                    `).join('')}
                  </div>
                </div>
              ` : ''}

              ${p.clinicalNotes ? `
                <div class="so-sec">
                  <div class="so-sec-label">${effectiveMode === 'transfer' ? 'Hospital Course & Active Plan' : 'Clinical Context'}</div>
                  <div class="so-sec-text so-prewrap">${escHtml(p.clinicalNotes)}</div>
                </div>
              ` : ''}

              ${consultList.length > 0 ? `
                <div class="so-sec">
                  <div class="so-sec-label">Consults</div>
                  <ul class="so-bullet-list">
                    ${consultList.map(c => {
                      const rec = (c.condensedNotes || c.notes || '').trim();
                      return `<li><strong>${escHtml(c.service)}</strong> <span class="so-muted">[${escHtml(c.status)}]</span>${rec ? ': ' + escHtml(rec) : ''}</li>`;
                    }).join('')}
                  </ul>
                </div>
              ` : ''}

              <div class="so-sec">
                <div class="so-sec-label">Action List (To-Dos)</div>
                ${openTasks.length === 0
                  ? `<div class="so-sec-text so-muted">None — no active pending tasks.</div>`
                  : `<ul class="so-task-list">
                      ${openTasks.map(t => `
                        <li class="${t.urgent ? 'so-task-urgent' : ''}">
                          <span class="so-chk-box">☐</span>
                          ${t.urgent ? '<span class="so-stat-tag">STAT</span> ' : ''}
                          <span class="so-cat-tag">[${escHtml(t.category)}]</span>
                          <span>${escHtml(t.text)}</span>
                        </li>
                      `).join('')}
                    </ul>`
                }
                ${opts.includeCompletedTasks && doneTasks.length > 0 ? `
                  <div class="so-done-wrap">
                    <div class="so-done-lbl">Completed Today:</div>
                    <ul class="so-task-list so-done-list">
                      ${doneTasks.map(t => `<li><span class="so-chk-box">☑</span> [${escHtml(t.category)}] ${escHtml(t.text)}</li>`).join('')}
                    </ul>
                  </div>
                ` : ''}
              </div>

              <div class="so-sec so-sec-cont">
                <div class="so-sec-label">Contingencies (If / Then)</div>
                <div class="so-sec-text">${escHtml(p.contingencies || 'Routine floor monitoring; call hospitalist for acute change in vitals or mental status.')}</div>
              </div>

              ${(effectiveMode === 'transfer' || p.priority === 'discharge') ? `
                <div class="so-sec">
                  <div class="so-sec-label">Disposition &amp; Barriers</div>
                  <div class="so-sec-text">${escHtml(p.disposition || 'Pending daily reassessment.')}</div>
                </div>
              ` : ''}

              ${gaps.length > 0 ? `
                <div class="so-sec so-sec-gaps">
                  <strong>Unchecked Checklist Items:</strong> ${escHtml(gaps.join(', '))}
                </div>
              ` : ''}
            </div>
          </article>
        `;
      }).join('');

    return `
      <div class="so-sheet">
        <header class="so-sheet-header">
          <div class="so-sheet-title">${escHtml(titleMap[opts.mode] || titleMap.shift)}</div>
          <div class="so-sheet-meta">
            <span><strong>Service:</strong> ${escHtml(state.serviceName || 'Hospitalist Medicine')}</span>
            <span><strong>Provider:</strong> ${escHtml(state.providerName || 'Hospitalist')}</span>
            <span><strong>Generated:</strong> ${escHtml(formatTimestamp())}</span>
          </div>
          <div class="so-sheet-counts">
            <span class="so-cnt-pill">Total: <strong>${sorted.length}</strong></span>
            <span class="so-cnt-pill so-cnt-sick">Sick: <strong>${sickCount}</strong></span>
            <span class="so-cnt-pill so-cnt-watcher">Watcher: <strong>${watcherCount}</strong></span>
            <span class="so-cnt-pill so-cnt-dc">D/C Today: <strong>${dcCount}</strong></span>
            <span class="so-cnt-pill so-cnt-stable">Stable: <strong>${stableCount}</strong></span>
            <span class="so-cnt-pill">Open Tasks: <strong>${openTaskCount}</strong></span>
          </div>
        </header>

        ${sickBannerHtml}

        <div class="so-sheet-cards">
          ${cardsHtml}
        </div>

        <footer class="so-sheet-footer">
          <strong>Receiver Synthesis:</strong> Review SICK &amp; WATCHER contingencies first, confirm pending STAT tasks, and clarify active questions.
        </footer>
      </div>
    `;
  }

  return {
    generateText,
    generateMarkdown,
    generateFormattedHtml,
    sortForHandoff
  };
})();

